import json, pandas as pd
from datetime import datetime

MAP = {"user_id":"user_id","id":"user_id","userId":"user_id",
       "email":"email","email_address":"email",
       "full_name":"name","name":"name","userName":"name",
       "registration_date":"created_date","created_at":"created_date","joined":"created_date",
       "status":"status"}
FIELDS = ["name","email","created_date","status"]

def norm_date(v):
    if v is None or (isinstance(v,float) and pd.isna(v)): return None
    if hasattr(v,"strftime"): return v.strftime("%Y-%m-%d")
    s = str(v).strip()
    for f in ("%Y-%m-%d","%Y/%m/%d","%m/%d/%Y","%d-%m-%Y","%Y-%m-%dT%H:%M:%S","%Y-%m-%d %H:%M:%S","%Y%m%d"):
        try: return datetime.strptime(s,f).strftime("%Y-%m-%d")
        except ValueError: pass
    return pd.to_datetime(s).strftime("%Y-%m-%d")

def to_bool(v):
    if isinstance(v,str): return v.strip().lower() in ("true","1","yes","y","t")
    return bool(v)

def normalize(df):
    out = {}
    for rec in df.to_dict("records"):
        r = {}
        for k,v in rec.items():
            if k in MAP: r[MAP[k]] = v
            elif k in ("is_active","active") and "status" not in rec and v is not None and not (isinstance(v,float) and pd.isna(v)):
                r["status"] = "active" if to_bool(v) else "inactive"
        if r.get("user_id") is None or pd.isna(r["user_id"]): continue
        r["user_id"] = int(r["user_id"])
        r["created_date"] = norm_date(r.get("created_date"))
        for f in FIELDS:
            v = r.get(f)
            if v is not None and isinstance(v,float) and pd.isna(v): v = None
            r[f] = None if v is None else str(v)
        out[r["user_id"]] = r
    return out

sources = {
    "source_a": normalize(pd.DataFrame(json.load(open("/data/source_a/users.json")))),
    "source_b": normalize(pd.read_csv("/data/source_b/users.csv", dtype=str)),
    "source_c": normalize(pd.read_parquet("/data/source_c/users.parquet")),
}
ids = sorted(set().union(*[s.keys() for s in sources.values()]))
rows, conflicts = [], []
for uid in ids:
    row = {"user_id": uid}
    for f in FIELDS:
        vals = {s: sources[s][uid][f] for s in sources if uid in sources[s] and sources[s][uid][f] is not None}
        sel = next(iter(vals.values()), None)
        row[f] = sel
        if len(set(vals.values())) > 1:
            conflicts.append({"user_id": uid, "field": f, "values": vals, "selected": sel})
    rows.append(row)

df = pd.DataFrame(rows, columns=["user_id","name","email","created_date","status"])
df["user_id"] = df["user_id"].astype("int64")
for c in ["name","email","created_date","status"]: df[c] = df[c].astype(object)
df.to_parquet("/app/merged_users.parquet", index=False)
json.dump({"total_conflicts": len(conflicts), "conflicts": conflicts}, open("/app/conflicts.json","w"), indent=2)
print(df); print(df.dtypes); print(json.dumps(conflicts, indent=1))
EOF
